                data[row] = switch(definition.columnResult) {
                    ResultType.SINGLE : data[row][colIndices[0]],
                    ResultType.ARRAY : mapArray(colIndices, function(index) { return data[row][index]; }),
                    ResultType.MAP : indexMap(colIndices, colLabels, data[row])
                };
            }
            // And now the rows
            value = switch(definition.rowResult) {
                ResultType.SINGLE : data[rowIndices[0]],
                ResultType.ARRAY : mapArray(rowIndices, function(index) { return data[index]; }),
                ResultType.MAP : indexMap(rowIndices, rowLabels, data)
            };
        }
        else if (definition.mode == VariableMode.MEASURED)
        {
            if (definition.measurementMode == VariableMeasurementMode.DISTANCE)
            {
                verifyNonemptyQuery(context, definition, "entityCouple", ErrorStringEnum.VARIABLE_SELECT_FIRST_ENTITY);

                var hasFlatEntities = false;
                if (!isAtVersionOrLater(context, FeatureScriptVersionNumber.V1846_BEND_LINE_ATTACHED))
                {
                    hasFlatEntities = !isQueryEmpty(context, definition.entityCouple->qSheetMetalFlatFilter(SMFlatType.YES));
                    if (hasFlatEntities && size(evaluateQuery(context, qOwnerBody(definition.entityCouple))) > 1)
                    {
                        throw regenError(ErrorStringEnum.VARIABLE_FLATTENED_ENTITIES_MUST_BE_SAME_BODY);
                    }
                }

                if (size(evaluateQuery(context, definition.entityCouple)) == 1)
                {
                    throw regenError(ErrorStringEnum.VARIABLE_SELECT_SECOND_ENTITY);
                }

                if (isAtVersionOrLater(context, FeatureScriptVersionNumber.V1846_BEND_LINE_ATTACHED))
                {
                    const flatOwnerBodySideA = getFlatOwnerBody(context, qNthElement(definition.entityCouple, 0));
                    const flatOwnerBodySideB = getFlatOwnerBody(context, qNthElement(definition.entityCouple, 1));
                    hasFlatEntities = flatOwnerBodySideA != undefined || flatOwnerBodySideB != undefined;

                    // If both entities are in flats, check that they're in the same flat.
                    if (flatOwnerBodySideA != undefined && flatOwnerBodySideB != undefined)
                    {
                        if (size(evaluateQuery(context, qUnion(flatOwnerBodySideA, flatOwnerBodySideB))) > 1)
                        {
                            throw regenError(ErrorStringEnum.VARIABLE_FLATTENED_ENTITIES_MUST_BE_SAME_BODY);
                        }
                    }
                    // Else, if either entity is in a flat, we're measuring between a flat and something else, so throw.
                    else if (hasFlatEntities)
                    {
                        throw regenError(ErrorStringEnum.VARIABLE_FLATTENED_ENTITIES_MUST_BE_SAME_BODY);
                    }
                }

                if (definition.componentSelector == AxisWithCustom.CUSTOM)
                {
                    verifyNonemptyQuery(context, definition, "customDirection", ErrorStringEnum.VARIABLE_SELECT_CUSTOM_DIRECTION);
                }

                const distanceResultMap = measureDistance(context, {
                            entities : definition.entityCouple,
                            measureFromAxis : definition.measureFromAxis,
                            customDirection : definition.customDirection,
                            extendEntities : definition.extendEntities,
                            maximum : definition.minmax == VariableMinMaxSelection.MAXIMUM
                        });
                value = selectDistanceComponent(distanceResultMap, definition.componentSelector);

                if (!hasFlatEntities)
                {
                    try silent
                    {
                        addDebugLine(context, distanceResultMap.firstPoint, distanceResultMap.secondPoint, DebugColor.MAGENTA);
                        if (definition.componentSelector != AxisWithCustom.DISTANCE && definition.componentSelector != AxisWithCustom.CUSTOM)
                        {
                            addAxisDecompositionDebugLines(context, distanceResultMap.firstPoint, distanceResultMap.secondPoint);
                        }
                        if (definition.componentSelector == AxisWithCustom.CUSTOM)
                        {
                            var customDirection = extractDirection(context, definition.customDirection);
                            if (dot(customDirection, normalize(distanceResultMap.secondPoint - distanceResultMap.firstPoint)) < 0)
                            {
                                customDirection *= -1;
                            }
                            addDebugLine(context, distanceResultMap.firstPoint, distanceResultMap.firstPoint + value * customDirection, DebugColor.CYAN);
                        }
                    }
                }

                // Show axis decomposition in the feature dialog
                setFeatureComputedParameter(context, id, { "name" : "distance", "value" : selectDistanceComponent(distanceResultMap, AxisWithCustom.DISTANCE) });
                setFeatureComputedParameter(context, id, { "name" : "xOffset", "value" : selectDistanceComponent(distanceResultMap, AxisWithCustom.X) });
                setFeatureComputedParameter(context, id, { "name" : "yOffset", "value" : selectDistanceComponent(distanceResultMap, AxisWithCustom.Y) });
                setFeatureComputedParameter(context, id, { "name" : "zOffset", "value" : selectDistanceComponent(distanceResultMap, AxisWithCustom.Z) });
                if (definition.componentSelector == AxisWithCustom.CUSTOM)
                {
                    setFeatureComputedParameter(context, id, { "name" : "customOffset", "value" : selectDistanceComponent(distanceResultMap, AxisWithCustom.CUSTOM) });
                }
                setHighlightedEntities(context, { "entities": definition.entityCouple });
            }
            else if (definition.measurementMode == VariableMeasurementMode.LENGTH)
            {
                verifyNonemptyQuery(context, definition, "lengthEntities", ErrorStringEnum.VARIABLE_SELECT_ENTITIES_TO_MEASURE);
                value = evLength(context, {
                    "entities" : definition.lengthEntities
                });
                setHighlightedEntities(context, { "entities": definition.lengthEntities });
            }
            else if (definition.measurementMode == VariableMeasurementMode.DIAMETER)
            {
                verifyNonemptyQuery(context, definition, "diameterEntity", ErrorStringEnum.VARIABLE_SELECT_ENTITY_TO_MEASURE);
                value = measureDiameter(context, {
                    entity: definition.diameterEntity,
                    radius: definition.radius
                });
                setHighlightedEntities(context, { "entities": definition.diameterEntity });
            }
            else if (definition.measurementMode == VariableMeasurementMode.ANGLE)
            {
                if (definition.angleType == AngleType.THREE_POINTS)
                {
                    verifyNonemptyQuery(context, definition, "angleVertex", ErrorStringEnum.VARIABLE_SELECT_ENTITIES_TO_MEASURE);
                    verifyNonemptyQuery(context, definition, "anglePoints", ErrorStringEnum.VARIABLE_SELECT_ENTITIES_TO_MEASURE);

                    const armList = evaluateQuery(context, definition.anglePoints);
                    if (size(armList) < 2)
                    {
                        throw regenError(ErrorStringEnum.VARIABLE_SELECT_SECOND_ENTITY, ["anglePoints"]);
                    }
                    if (size(armList) > 2)
                    {
                        throw regenError(ErrorStringEnum.VARIABLE_ONLY_TWO_ENTITIES_ALLOWED, ["anglePoints"]);
                    }

                    const vertexPoint = pointFromEntity(context, definition.angleVertex);
                    value = measureThreePointAngle(context, vertexPoint,
                        pointFromEntity(context, armList[0]), pointFromEntity(context, armList[1]),
                        definition.complementAngle);

                    setHighlightedEntities(context, { "entities": qUnion(definition.angleVertex, definition.anglePoints) });
                }
                else
                {
                    verifyNonemptyQuery(context, definition, "angleEntities", ErrorStringEnum.VARIABLE_SELECT_ENTITIES_TO_MEASURE);

                    const angleEntityList = evaluateQuery(context, definition.angleEntities);
                    if (size(angleEntityList) < 2)
                    {
                        throw regenError(ErrorStringEnum.VARIABLE_SELECT_SECOND_ENTITY, ["angleEntities"]);
                    }
                    if (size(angleEntityList) > 2)
                    {
                        throw regenError(ErrorStringEnum.VARIABLE_ONLY_TWO_ENTITIES_ALLOWED, ["angleEntities"]);
                    }

                    value = measureAngleBetween(context, angleEntityList[0], angleEntityList[1], definition.complementAngle);

                    setHighlightedEntities(context, { "entities": definition.angleEntities });
                }

                setFeatureComputedParameter(context, id, { "name" : "angleReadout", "value" : value });
            }
            else if (definition.measurementMode == VariableMeasurementMode.CURVATURE)
            {
                verifyNonemptyQuery(context, definition, "curvatureEdge", ErrorStringEnum.VARIABLE_SELECT_ENTITY_TO_MEASURE);
                value = measureRadiusOfCurvature(context, id, definition);
                setFeatureComputedParameter(context, id, { "name" : "radiusReadout", "value" : value });
                setHighlightedEntities(context, { "entities": definition.curvatureEdge });
            }
            else if (definition.measurementMode == VariableMeasurementMode.COORDINATE)
            {
                verifyNonemptyQuery(context, definition, "coordinateEntity", ErrorStringEnum.VARIABLE_SELECT_ENTITY_TO_MEASURE);
                const coordPoint = pointFromEntity(context, definition.coordinateEntity);
                setFeatureComputedParameter(context, id, { "name" : "coordX", "value" : coordPoint[0] });
                setFeatureComputedParameter(context, id, { "name" : "coordY", "value" : coordPoint[1] });
                setFeatureComputedParameter(context, id, { "name" : "coordZ", "value" : coordPoint[2] });
                value = selectCoordinate(coordPoint, definition.coordinateComponent);
                setHighlightedEntities(context, { "entities": definition.coordinateEntity });
            }
        }

        verifyVariableName(context, definition.name, "name");
        publishVariableValue(definition.name, context, id, value, definition.description);
    },
    {
        // Default mode is ASSIGNED.
        mode : VariableMode.ASSIGNED,
        description : "",
        variableType : VariableType.ANY,

        // If mode is set to MEASURED, the default measurement mode is DISTANCE.
        measurementMode : VariableMeasurementMode.DISTANCE,
        componentSelector : AxisWithCustom.DISTANCE,

        distance : 0 * meter,
        xOffset : 0 * meter,
        yOffset : 0 * meter,
        zOffset : 0 * meter,
        customOffset : 0 * meter,

        entityCouple : qNothing(),
        lengthEntities : qNothing(),
        diameterEntity : qNothing(),
        angleType : AngleType.BETWEEN_ENTITIES,
        angleEntities : qNothing(),
        angleVertex : qNothing(),
        anglePoints : qNothing(),
        complementAngle : false,
        angleReadout : 0 * degree,

        curvatureEdge : qNothing(),
        curvaturePoint : qNothing(),
        minimumRadius : false,
        minRadiusParameter : 0,
        radiusReadout : 0 * meter,

        coordinateEntity : qNothing(),
        coordinateComponent : PointComponent.X,
        coordX : 0 * meter,
        coordY : 0 * meter,
        coordZ : 0 * meter,

        // MEASURED mode options are set such that the ability to enable them is true, but the default value is false.
        // In the case of the UI, the editing logic handles updating these defaults to their appropriate values.
        minmax: VariableMinMaxSelection.MINIMUM,
        extendEntities: false,
        measureFromAxis: false,
        radius: false,
        initEntities: qNothing(),

        // TABLE mode.
        rowAccessType : AccessType.INDEX,
        rowIndex: 0,
        rowValue: "",
        rowRegexp: false,
        rowMinIndex: 0,
        rowMaxIndex: 0,
        rowResult: ResultType.SINGLE,
        rowLabelIndex: 0,
        columnAccessType : AccessType.INDEX,
        columnIndex: 0,
        columnValue: "",
        columnRegexp: false,
        columnMinIndex: 0,
        columnMaxIndex: 0,
        columnResult: ResultType.SINGLE,
        columnLabelIndex: 0,
        useConversionFactor: false,
        conversionFactor: 0
    });

/**
 *  @internal
 *  This is a somewhat trimmed down version of defineFeature that calls a very trimmed down version
 *  of assignVariable, except that the precondition is defined in this function so that the annotation will work.
 *  This is only meant to be used by variable studios.
 *  It only supports VariableMode.ASSIGNED, and it skips some of the overhead added by defineFeature.
 */
annotation { "Feature Type Name" : "VariableStudioVariable",
        "Feature Name Template" : "###name = #value",
        "UIHint" : UIHint.NO_PREVIEW_PROVIDED,
        "Tooltip Template" : "###name = #value #description" }
export function variableStudioAssignVariable(context is Context, id is Id, definition is map)
precondition
{
    annotation { "Name" : "Variable type", "UIHint" : ["HORIZONTAL_ENUM", "UNCONFIGURABLE"] }
    definition.variableType is VariableType;

    annotation { "Name" : "Name", "UIHint" : [UIHint.UNCONFIGURABLE, UIHint.VARIABLE_NAME], "MaxLength" : 10000 }
    definition.name is string;

    if (definition.variableType == VariableType.LENGTH)
    {
        annotation { "Name" : "Value", "UIHint" : UIHint.INITIAL_FOCUS_ON_EDIT }
        isLength(definition.lengthValue, ZERO_DEFAULT_LENGTH_BOUNDS);
    }
    else if (definition.variableType == VariableType.ANGLE)
    {
        annotation { "Name" : "Value", "UIHint" : UIHint.INITIAL_FOCUS_ON_EDIT }
        isAngle(definition.angleValue, ANGLE_360_ZERO_DEFAULT_BOUNDS);
    }
    else if (definition.variableType == VariableType.NUMBER)
    {
        annotation { "Name" : "Value", "UIHint" : UIHint.INITIAL_FOCUS_ON_EDIT }
        isReal(definition.numberValue, { (unitless) : [-1e12, 0, 1e12] } as RealBoundSpec);
    }
    else if (definition.variableType == VariableType.ANY)
    {
        annotation { "Name" : "Value", "UIHint" : UIHint.INITIAL_FOCUS_ON_EDIT }
        isAnything(definition.anyValue);
    }

    if (definition.description != undefined)
    {
        annotation { "Name" : "Description", "MaxLength" : 256, "Default" : "" }
        definition.description is string;
    }
}
{
    var token is map = {};
    var started = false;
    try
    {
        var visible = definition; /* visible to feature */
        definition.lock = true;
        visible.asVersion = undefined; // Don't let the feature body know if there's been an upgrade
        token = @startFeature(context, id, definition);
        started = true;

        // we need these to support parameter visibility checks based on the real assignVariable feature
        @setFeatureComputedParameter(context, id, { "name" : "variableType", "value" : definition.variableType });
        @setFeatureComputedParameter(context, id, { "name" : "mode", "value" : VariableMode.ASSIGNED });
        @setFeatureComputedParameter(context, id, { "name" : "description", "value" : definition.description });

        // call the very trimmed down version of assignVariable
        variableStudioAssignVariableInternal(context, id, visible);

        const error = getFeatureError(context, id);
        if (error != undefined && error != ErrorStringEnum.NO_ERROR)
        {
            if (!isTopLevelId(id))
                throw regenError(error);
            else
                @abortFeature(context, id, token);
        }
        else
        {
            @endFeature(context, id, token);
        }
    }
    catch (error)
    {
        if (try(processError(context, id, error)) == undefined)
            reportFeatureError(context, id, ErrorStringEnum.REGEN_ERROR);
        if (started)
            @abortFeature(context, id, token);
        if (!isTopLevelId(id))
            throw error; // rethrow
    }
}

function variableStudioAssignVariableInternal(context is Context, id is Id, definition is map)
{
    var value;
    if (definition.variableType == VariableType.LENGTH)
        value = definition.lengthValue;
    else if (definition.variableType == VariableType.ANGLE)
        value = definition.angleValue;
    else if (definition.variableType == VariableType.NUMBER)
        value = definition.numberValue;
    else if (definition.variableType == VariableType.ANY)
        value = definition.anyValue;

    if (isAtVersionOrLater(context, FeatureScriptVersionNumber.V424_VARIABLE_WARNINGS))
    {
        if (value == undefined)
        {
            reportFeatureWarning(context, id, ErrorStringEnum.VARIABLE_CANNOT_EVALUATE);
        }
    }

    if (definition.name == '' && isAtVersionOrLater(context, FeatureScriptVersionNumber.V2995_REMOVE_NAME_WORKAROUND))
        setFeatureComputedParameter(context, id, { "name" : "name", "value" : "?" });

    verifyVariableName(context, definition.name, "name");
    publishVariableValue(definition.name, context, id, value, definition.description);
}

/**
 * Throws an error if `name` is not a valid identifier.
 */
export function verifyVariableNameIsValid(name is string, faultyParameter is string)
{
    if (length(name) > 10000)
        throw regenError(ErrorStringEnum.VARIABLE_NAME_TOO_LONG, [faultyParameter]);
    const replaceNameWithRegExpShouldBeBlank = replace(name, '[a-zA-Z_][a-zA-Z_0-9]*', '');
    if (name == '' || replaceNameWithRegExpShouldBeBlank != '')
        throw regenError(ErrorStringEnum.VARIABLE_NAME_INVALID, [faultyParameter]);
}

/**
 * Throws an error if `name` is not a valid identifier or is used by a query variable.
 */
export function verifyVariableName(context is Context, name is string, faultyParameter is string)
{
    verifyVariableNameIsValid(name, faultyParameter);
    var exists = false;
    try silent
    {
        @getQueryVariable(context, { "name" : name});
        exists = true;
    }
    if (exists)
    {
        throw regenError(ErrorStringEnum.VARIABLE_NAME_ALREADY_USED_IN_QUERY_VARIABLE, [faultyParameter]);
    }
}

function publishVariableValue(name is string, context is Context, id is Id, value, description)
{
    setVariable(context, name, value, (description is string) ? description : "");
    const quotedValue = (value is string) ? ('"' ~ value ~ '"') : value;
    setFeatureComputedParameter(context, id, { "name" : "value", "value" : quotedValue });
}

/**
 * Make a function to look up variables from the given context.  Used in generated part studio code.
 */
export function makeLookupFunction(context is Context, id is Id) returns function
{
    return (name is string) => getVariable(context, name);
}

/** Measure the distance between two entities.
 * @param context {Context}
 * @param arg {{
 *     @field entities {Query} : a query containing two entities to measure the distance between.
 *     @field measureFromAxis {boolean} : measure from the axis of the selected geometry, if an axis is available. Incompatible with the `maximum` option. Defaults to `false`. @optional
 *     @field customDirection {Query} : measure the distance between two entities along a direction selected by this query. @optional
 *     @field extendEntities {boolean} : extend the entities out to infinity. Incompatible with the `maximum` option. Defaults to `false`. @optional
 *     @field maximum {boolean} : measure the maximum distance between the selected entities, instead of the minimum by default. Defaults to `false`. @optional
 * }}
 */
export function measureDistance(context is Context, arg is map) returns map
precondition
{
    arg.entities is Query;
    arg.measureFromAxis == undefined || arg.measureFromAxis is boolean;
    arg.customDirection == undefined || arg.customDirection is Query;
    arg.extendEntities == undefined || arg.extendEntities is boolean;
    arg.maximum == undefined || arg.maximum is boolean;
}
{
    const maximum = arg.maximum == true;
    const measureFromAxis = !maximum && arg.measureFromAxis == true;
    const extendEntities = !maximum && arg.extendEntities == true;

    const flattenedEntitiesMap = prepareSideEntities(context, arg.entities, measureFromAxis);

    const sideASet = flattenedEntitiesMap.axisEntitiesMap.linesAside == [] ? flattenedEntitiesMap.entityAQuery : flattenedEntitiesMap.axisEntitiesMap.linesAside;
    const sideBSet = flattenedEntitiesMap.axisEntitiesMap.linesBside == [] ? flattenedEntitiesMap.entityBQuery : flattenedEntitiesMap.axisEntitiesMap.linesBside;

    const extendSideA = extendEntities || sideContainsConstructionPlanes(context, sideASet);
    const extendSideB = extendEntities || sideContainsConstructionPlanes(context, sideBSet);

    if ((extendSideA || extendSideB) && maximum) {
        throw regenError(ErrorStringEnum.VARIABLE_CANNOT_USE_MAXIMUM_WITH_INFINITE_ENTITIES);
    }

    var distanceResult is DistanceResult = evDistance(context, {
            "side0" : sideASet,
            "side1" : sideBSet,
            "extendSide0" : extendSideA,
            "extendSide1" : extendSideB,
            "maximum" : maximum
        });

    const entityOnSideA = getSideEntity(sideASet, distanceResult, 0);
    const entityOnSideB = getSideEntity(sideBSet, distanceResult, 1);

    distanceResult = recomputeForInfiniteEntitiesIfNeeded(context, extendEntities, entityOnSideA, entityOnSideB, distanceResult);

    const distanceMap = {
        "distance" : distanceResult.distance,
        "firstPoint" : distanceResult.sides[0].point,
        "secondPoint" : distanceResult.sides[1].point,
        "side0" : entityOnSideA,
        "side1" : entityOnSideB,
        "customDirection" : arg.customDirection
    };

    return addAxisDecomposition(context, distanceMap);
}

/**
 * Returns appropriate entry in distanceMap returned from measureDistance given the selected AxisWithCustom.
 */
export function selectDistanceComponent(distanceMap is map, componentSelector is AxisWithCustom)
{
    return switch (componentSelector)
        {
                AxisWithCustom.DISTANCE : distanceMap.distance,
                AxisWithCustom.X : distanceMap.xOffset,
                AxisWithCustom.Y : distanceMap.yOffset,
                AxisWithCustom.Z : distanceMap.zOffset,
                AxisWithCustom.CUSTOM : distanceMap.customOffset
            };
}

/** Measure the diameter (or radius) of the selected entity.
 * @param context {Context}
 * @param arg {{
 *     @field entity {Query} : a query containing an entity of GeometryType.CIRCLE, GeometryType.ARC, GeometryType.CYLINDER, or GeometryType.SPHERE.
 *     @field radius {boolean} : measure the radius instead of the diameter. Defaults to `false`. @optional
 * }}
 */
export function measureDiameter(context is Context, arg is map)
precondition
{
    arg.entity is Query;
    arg.radius == undefined || arg.radius is boolean;
}
{
    var curveQuery = qUnion([
            qGeometry(arg.entity, GeometryType.CIRCLE),
            qGeometry(arg.entity, GeometryType.ARC)
        ]);

    var surfaceQuery = qUnion([
            qGeometry(arg.entity, GeometryType.CYLINDER),
            qGeometry(arg.entity, GeometryType.SPHERE)
        ]);

    var radius;
    if (evaluateQuery(context, curveQuery) != [])
    {
        radius = evCurveDefinition(context, { "edge" : curveQuery }).radius;
    }
    else if (evaluateQuery(context, surfaceQuery) != [])
    {
        radius = evSurfaceDefinition(context, { "face" : surfaceQuery }).radius;
    }
    else
    {
        throw regenError(ErrorStringEnum.VARIABLE_NO_GEOMETRY_WITH_DIAMETER);
    }

    return  arg.radius == true ? radius : 2 * radius;
}

/**
 * Processing of the initial queries before distance evaluation
 */
function prepareSideEntities(context is Context, entities is Query, axisMode is boolean) returns map
{
    var entityAQuery = undefined;
    var entityBQuery = undefined;

    if (size(evaluateQuery(context, entities)) > 2)
    {
        throw regenError(ErrorStringEnum.VARIABLE_ONLY_TWO_ENTITIES_ALLOWED);
    }
    entityAQuery = splitToSubEntities(qNthElement(entities, 0));
    entityBQuery = splitToSubEntities(qNthElement(entities, 1));

    var axisEntitiesMap = {
        "linesAside" : [],
        "indexAside" : [],
        "linesBside" : [],
        "indexBside" : []
    };

    // Calculate axis map only when "Use axis" option is active.
    if (axisMode)
    {
        // Locate possible axis entities on side A and B.
        var axisMapSideA = replaceWithCenterLines(context, entityAQuery);
        var axisMapSideB = replaceWithCenterLines(context, entityBQuery);
        if (axisMapSideA != { "axisArray" : [], "indexArray" : [] } || axisMapSideB != { "axisArray" : [], "indexArray" : [] })
        {
            axisEntitiesMap = {
                    "linesAside" : axisMapSideA.axisArray,
                    "indexAside" : axisMapSideA.indexArray,
                    "linesBside" : axisMapSideB.axisArray,
                    "indexBside" : axisMapSideB.indexArray
                };
        }
        else
        {
            throw regenError(ErrorStringEnum.VARIABLE_NO_AXIS_ENTITIES);
        }
    }

    return {
            "entityAQuery" : entityAQuery,
            "entityBQuery" : entityBQuery,
            "axisEntitiesMap" : axisEntitiesMap
        };
}

/**
 * Turn a body query into a query for its sub-entities.
 */
function splitToSubEntities(queryToSplit is Query) returns Query
{
    return qSubtraction(qUnion([queryToSplit, qOwnedByBody(queryToSplit)]), qEntityFilter(queryToSplit, EntityType.BODY));
}

/**
 * Replace side entities with their axes (excludes lines, planes, and mate connectors).
 */
function replaceWithCenterLines(context, entityQuery is Query) returns map
{
    var axisArray = [];
    var indexArray = [];

    for (var i, singleEntity in evaluateQuery(context, entityQuery))
    {
        const axis = getAxis(context, singleEntity);
        if (axis != undefined)
        {
            axisArray = append(axisArray, axis);
            indexArray = append(indexArray, i);
        }
    }
    return { "axisArray" : axisArray, "indexArray" : indexArray };
}

/**
 * Returns axis of the entity if it belongs to GeometryType ARC, CIRCLE, CYLINDER, CONE, TORUS, or REVOLVED.
 */
function getAxis(context is Context, entity is Query)
{
    const axis = try silent(evAxis(context, { "axis" : entity }));
    if (axis == undefined)
    {
        return undefined;
    }

    const approvedGeometryTypes = [
            GeometryType.ARC,
            GeometryType.CIRCLE,
            GeometryType.CYLINDER,
            GeometryType.CONE,
            GeometryType.TORUS,
            GeometryType.REVOLVED
        ];

    const queriesForApprovedGeometryTypes = mapArray(approvedGeometryTypes, geomType => qGeometry(entity, geomType));

    if (!isQueryEmpty(context, qUnion(queriesForApprovedGeometryTypes)))
        return axis;
    else
        return undefined;
}

/**
 * Computes the different axis measurements for a distance measurement.
 */
function addAxisDecomposition(context is Context, distanceMap is map) returns map
{
    var axisDecomposition =
    {
        "xOffset" : 0 * meter,
        "yOffset" : 0 * meter,
        "zOffset" : 0 * meter,
        "customOffset" : 0 * meter,
        "pointA" : undefined,
        "pointB" : undefined
    };
    if (distanceMap.distance != 0 * meter)
    {
        // Calculate offset components.
        axisDecomposition.xOffset = abs(distanceMap.firstPoint[0] - distanceMap.secondPoint[0]);
        axisDecomposition.yOffset = abs(distanceMap.firstPoint[1] - distanceMap.secondPoint[1]);
        axisDecomposition.zOffset = abs(distanceMap.firstPoint[2] - distanceMap.secondPoint[2]);

        axisDecomposition.pointA = vector([distanceMap.secondPoint[0], distanceMap.firstPoint[1], distanceMap.firstPoint[2]]);
        axisDecomposition.pointB = vector([distanceMap.secondPoint[0], distanceMap.secondPoint[1], distanceMap.firstPoint[2]]);

        // Calculate projection length on custom vector.
        if (distanceMap.customDirection != undefined && !isQueryEmpty(context, distanceMap.customDirection))
        {
            const direction = extractDirection(context, distanceMap.customDirection);
            const projectLine = line(WORLD_ORIGIN, direction);

            var pointCA = project(projectLine, distanceMap.firstPoint);
            var pointCB = project(projectLine, distanceMap.secondPoint);
            var customDistance = norm(pointCB - pointCA);

            axisDecomposition = mergeMaps(axisDecomposition, { "customOffset" : customDistance, "pointCA" : pointCA, "pointCB" : pointCB });
        }
    }
    return mergeMaps(distanceMap, axisDecomposition);
}

function addAxisDecompositionDebugLines(context is Context, from is Vector, to is Vector)
{
    const difference = to - from;
    var current = from;
    for (var axis = 0; axis < 3; axis += 1)
    {
        var next = current;
        next[axis] += difference[axis];
        addDebugLine(context, current, next, AXIS_COLORS[axis]);
        current = next;
    }
}

/**
 * For one of the sides of a DistanceResult, return the entity or line where the extremum was found.
 */
function getSideEntity(sideInput, distanceResult is DistanceResult, sideIndex is number)
{
    var entityIndex = distanceResult.sides[sideIndex].index;
    if (sideInput is Query)
    {
        return qNthElement(sideInput, entityIndex);
    }
    else
    {
        return sideInput[entityIndex];
    }
}

/**
 * When we have two infinite entities, there may be an infinite number of closest points, so recompute from one of the sides.
 * This lets us put the debug line on the actual entities.
 */
function recomputeForInfiniteEntitiesIfNeeded(context is Context, extendEntities is boolean, side0, side1, distanceResult is map) returns map
{
    const lineSide0 = getLineFromSide(context, side0);
    const lineSide1 = getLineFromSide(context, side1);

    if (lineSide0 == undefined || lineSide1 == undefined || !parallelVectors(lineSide0.direction, lineSide1.direction))
    {
        return distanceResult;
    }

    // If either of the sides is an infinite line (from axis entities), or we're extending edges, recompute.
    if (side0 is Line || side1 is Line || extendEntities)
    {
        distanceResult.sides[0].point = lineSide0.origin;
        distanceResult.sides[1].point = evDistance(context, {
                        "side0" : lineSide1,
                        "side1" : distanceResult.sides[0].point
                    }).sides[0].point;
    }

    return distanceResult;
}

/**
 * Return line defnition from side when it is a Line or a linear edge.
 */
function getLineFromSide(context is Context, sideEntity)
{
    if (sideEntity is Line)
    {
        return sideEntity;
    }
    else if (sideEntity is Query && !isQueryEmpty(context, qGeometry(sideEntity, GeometryType.LINE)))
    {
        return evLine(context, { "edge" : sideEntity });
    }
    return undefined;
}

/**
 * Endpoints of an edge with the unit tangent at each, oriented to point AWAY from
 * that endpoint along the edge. Two edges meeting at a shared endpoint then yield
 * their interior corner angle. Works for any edge: line, arc, spline, or bspline.
 * At parameter 0 the tangent already points into the edge (away from the start
 * vertex); at parameter 1 it points out past the end, so it is negated.
 */
function edgeEndpointsAwayFromVertex(context is Context, edge is Query) returns array
{
    const lines = evEdgeTangentLines(context, { "edge" : edge, "parameters" : [0, 1] });
    return [
        { "point" : lines[0].origin, "dir" : normalize(lines[0].direction) },
        { "point" : lines[1].origin, "dir" : normalize(-1 * lines[1].direction) }
    ];
}

/**
 * Measure the angle between two selected entities, dispatching on type:
 *  - Two edges that share a vertex (lines, arcs, splines, bsplines): the angle
 *    between their tangents at that shared vertex -- the true intersection angle.
 *  - Otherwise (lines, axes, planar faces, mate connectors, or non-touching edges):
 *    the angle between their constant directions (face normal for a plane, axis for
 *    a mate connector or cylinder). Direction-only, so parallel, perpendicular, and
 *    skew all work without an intersection point.
 * Throws only when a curved edge is paired with something it does not intersect,
 * because no intersection angle is defined in that case.
 */
function measureAngleBetween(context is Context, e0 is Query, e1 is Query, complement is boolean) returns ValueWithUnits
{
    const bothEdges = !isQueryEmpty(context, e0->qEntityFilter(EntityType.EDGE))
        && !isQueryEmpty(context, e1->qEntityFilter(EntityType.EDGE));

    if (bothEdges)
    {
        const ends0 = edgeEndpointsAwayFromVertex(context, e0);
        const ends1 = edgeEndpointsAwayFromVertex(context, e1);
        for (var a in ends0)
        {
            for (var b in ends1)
            {
                if (norm(a.point - b.point) < TOLERANCE.zeroLength * meter)
                {
                    const armLength = 0.5 * min([evLength(context, { "entities" : e0 }), evLength(context, { "entities" : e1 })]);
                    try silent
                    {
                        drawAngleDebug(context, a.point, a.dir, b.dir, armLength);
                    }
                    return angleBetweenDirections(a.dir, b.dir, complement);
                }
            }
        }
    }

    return generalEntityAngle(context, e0, e1, complement);
}

/**
 * Angle for entities that each carry a constant direction: lines, axes, mate
 * connectors, and planar faces. `extractDirection` returns the face NORMAL for a
 * planar face and the line direction otherwise, so the raw angle is adjusted by type:
 *  - exactly one planar face -> the line-to-plane angle (90 - angle to the normal)
 *  - both planar faces       -> the dihedral angle (angle between normals), unchanged
 *  - neither                 -> the line/axis/connector angle, unchanged
 */
function generalEntityAngle(context is Context, e0 is Query, e1 is Query, complement is boolean) returns ValueWithUnits
{
    const a0 = entityDirectionAndPoint(context, e0, e1);
    const a1 = entityDirectionAndPoint(context, e1, e0);

    var theta = angleBetweenDirections(a0.dir, a1.dir, false);

    if (isPlanarFace(context, e0) != isPlanarFace(context, e1))
    {
        theta = abs(90 * degree - theta);
    }

    const anchor = (a0.point != undefined) ? a0.point : a1.point;
    const armLength = debugArmLength(context, e0, e1);
    if (anchor != undefined && armLength != undefined)
    {
        try silent
        {
            drawAngleDebug(context, anchor, a0.dir, a1.dir, armLength);
        }
    }

    if (complement)
    {
        theta = 180 * degree - theta;
    }
    return theta;
}

/**
 * Whether the entity is a non-linear edge (arc, spline, circle): an edge that is not
 * a straight line. Such an edge has no single direction, and evAxis would return its
 * central axis -- not its tangent -- so it must be routed through the tangent path.
 */
function isCurvedEdge(context is Context, entity is Query) returns boolean
{
    return !isQueryEmpty(context, entity->qEntityFilter(EntityType.EDGE))
        && isQueryEmpty(context, entity->qGeometry(GeometryType.LINE));
}

/**
 * A reference point for an entity: a vertex position or a mate connector origin.
 * Returns undefined for entities without a single characteristic point.
 */
function referencePoint(context is Context, entity is Query)
{
    if (!isQueryEmpty(context, entity->qEntityFilter(EntityType.VERTEX)))
    {
        return evVertexPoint(context, { "vertex" : entity });
    }
    if (!isQueryEmpty(context, entity->qBodyType(BodyType.MATE_CONNECTOR)))
    {
        return evMateConnector(context, { "mateConnector" : entity }).origin;
    }
    return undefined;
}

/**
 * Unit tangent of a curved edge at the point on the edge closest to `point`. The
 * parameter from evDistance is clamped to [0, 1] before the tangent is evaluated.
 */
function curveTangentAtPoint(context is Context, edge is Query, point is Vector) returns Vector
{
    const proj = evDistance(context, { "side0" : edge, "side1" : point });
    const param = clamp(proj.sides[0].parameter, 0, 1);
    const tangent = evEdgeTangentLine(context, { "edge" : edge, "parameter" : param });
    return normalize(tangent.direction);
}

/**
 * The direction to use for an entity, plus an anchor point when available. A curved
 * edge uses its tangent at the partner's point; every other entity uses extractDirection
 * (the normal for a planar face, the axis for a line, mate connector, or cylinder).
 */
function entityDirectionAndPoint(context is Context, entity is Query, partner is Query) returns map
{
    if (isCurvedEdge(context, entity))
    {
        const p = referencePoint(context, partner);
        if (p == undefined)
        {
            throw regenError("Cannot measure the highlighted curved edge against the other selection. Pair a curved edge with an edge it shares a vertex with, or a mate connector that lies on it.", entity);
        }
        return { "dir" : curveTangentAtPoint(context, entity, p), "point" : p };
    }

    const d = extractDirection(context, entity);
    if (d == undefined)
    {
        throw regenError("Cannot determine a direction from the highlighted entity.", entity);
    }
    return { "dir" : normalize(d), "point" : referencePoint(context, entity) };
}

/**
 * Half the length of the shorter selected edge, used to scale the debug drawing.
 * Returns undefined when neither selection is an edge.
 */
function debugArmLength(context is Context, e0 is Query, e1 is Query)
{
    var lengths = [];
    if (!isQueryEmpty(context, e0->qEntityFilter(EntityType.EDGE)))
    {
        lengths = append(lengths, evLength(context, { "entities" : e0 }));
    }
    if (!isQueryEmpty(context, e1->qEntityFilter(EntityType.EDGE)))
    {
        lengths = append(lengths, evLength(context, { "entities" : e1 }));
    }
    if (size(lengths) == 0)
    {
        return undefined;
    }
    return 0.5 * min(lengths);
}

/**
 * Radius of curvature of a curve, either at a picked point or -- when
 * definition.minimumRadius is set -- the minimum radius found by sampling along the
 * whole curve. In the minimum case the curve parameter of the tightest point is
 * reported (minRadiusParameter) and the location is drawn as a debug point. The
 * minimum is found by dense sampling, so it is approximate, not analytically exact.
 */
function measureRadiusOfCurvature(context is Context, id is Id, definition is map) returns ValueWithUnits
{
    const edge = definition.curvatureEdge;

    if (definition.minimumRadius)
    {
        const samples = 200;
        var params = [];
        for (var i = 0; i <= samples; i += 1)
        {
            params = append(params, i / samples);
        }

        const curvatures = evEdgeCurvatures(context, { "edge" : edge, "parameters" : params });
        var bestIndex = 0;
        for (var i = 1; i < size(curvatures); i += 1)
        {
            if (curvatures[i].curvature > curvatures[bestIndex].curvature)
            {
                bestIndex = i;
            }
        }

        const maxCurvature = curvatures[bestIndex].curvature;
        if (maxCurvature < 1e-6 / meter)
        {
            throw regenError("The curve is effectively straight; its radius of curvature is unbounded.", definition.curvatureEdge);
        }

        const minRadius = 1 / maxCurvature;
        setFeatureComputedParameter(context, id, { "name" : "minRadiusParameter", "value" : params[bestIndex] });
        try silent
        {
            drawCurvatureDebug(context, curvatures[bestIndex].frame, minRadius);
        }
        return minRadius;
    }

    verifyNonemptyQuery(context, definition, "curvaturePoint", ErrorStringEnum.VARIABLE_SELECT_ENTITY_TO_MEASURE);
    const pt = pointFromEntity(context, definition.curvaturePoint);
    const proj = evDistance(context, { "side0" : edge, "side1" : pt });
    const param = clamp(proj.sides[0].parameter, 0, 1);
    const cv = evEdgeCurvature(context, { "edge" : edge, "parameter" : param });
    if (cv.curvature < 1e-6 / meter)
    {
        throw regenError("The curve is effectively straight at this point; its radius of curvature is unbounded.", definition.curvatureEdge);
    }
    const radius = 1 / cv.curvature;
    try silent
    {
        drawCurvatureDebug(context, cv.frame, radius);
    }
    return radius;
}

/**
 * Visualize a radius of curvature: mark the point on the curve (red), draw the radius
 * along the Frenet normal (the frame xAxis, which points toward the center of
 * curvature) to that center, and mark the center (green).
 */
function drawCurvatureDebug(context is Context, frame is CoordSystem, radius is ValueWithUnits)
{
    const center = frame.origin + radius * frame.xAxis;
    addDebugPoint(context, frame.origin, DebugColor.RED);
    addDebugLine(context, frame.origin, center, DebugColor.BLUE);
    addDebugPoint(context, center, DebugColor.GREEN);
}

/**
 * The chosen component (X, Y, or Z) of a point's position.
 */
function selectCoordinate(point is Vector, component is PointComponent) returns ValueWithUnits
{
    if (component == PointComponent.X)
    {
        return point[0];
    }
    if (component == PointComponent.Y)
    {
        return point[1];
    }
    return point[2];
}

/**
 * Whether the entity has planar geometry (a planar face or datum plane).
 */
function isPlanarFace(context is Context, entity is Query) returns boolean
{
    return !isQueryEmpty(context, entity->qGeometry(GeometryType.PLANE));
}

/**
 * World point of a vertex or mate connector, for three-point angle measurement.
 */
function pointFromEntity(context is Context, entity is Query) returns Vector
{
    if (!isQueryEmpty(context, entity->qEntityFilter(EntityType.VERTEX)))
    {
        return evVertexPoint(context, { "vertex" : entity });
    }
    return evMateConnector(context, { "mateConnector" : entity }).origin;
}

/**
 * Angle subtended at `vertexPt` by the rays to `armA` and `armB` (angle A-V-B).
 */
function measureThreePointAngle(context is Context, vertexPt is Vector, armA is Vector, armB is Vector, complement is boolean) returns ValueWithUnits
{
    const v0 = armA - vertexPt;
    const v1 = armB - vertexPt;
    if (norm(v0) < TOLERANCE.zeroLength * meter || norm(v1) < TOLERANCE.zeroLength * meter)
    {
        throw regenError("An end point coincides with the vertex. Pick three distinct points.", ["anglePoints"]);
    }

    const dir0 = normalize(v0);
    const dir1 = normalize(v1);
    const armLength = 0.5 * min([norm(v0), norm(v1)]);
    try silent
    {
        drawAngleDebug(context, vertexPt, dir0, dir1, armLength);
    }
    return angleBetweenDirections(dir0, dir1, complement);
}

/**
 * Draw a visualization of the measured angle: a ray along each direction from the
 * vertex plus a short arc swept between them. Always called inside try silent, since
 * debug geometry must never block the measurement itself. The swept direction uses
 * Rodrigues' rotation of dir0 about the axis normal to both directions; since that
 * axis is perpendicular to dir0, the formula reduces to dir0*cos + (axis x dir0)*sin.
 */
function drawAngleDebug(context is Context, vertex is Vector, dir0 is Vector, dir1 is Vector, armLength is ValueWithUnits)
{
    addDebugLine(context, vertex, vertex + armLength * dir0, DebugColor.GREEN);
    addDebugLine(context, vertex, vertex + armLength * dir1, DebugColor.GREEN);

    const axisV = cross(dir0, dir1);
    if (norm(axisV) > TOLERANCE.zeroAngle)
    {
        const axis = normalize(axisV);
        const sweep = angleBetweenDirections(dir0, dir1, false);
        const radius = armLength * 0.5;
        const segments = 16;
        var prev = vertex + radius * dir0;
        for (var i = 1; i <= segments; i += 1)
        {
            const a = sweep * i / segments;
            const swept = dir0 * cos(a) + cross(axis, dir0) * sin(a);
            const cur = vertex + radius * swept;
            addDebugLine(context, prev, cur, DebugColor.BLUE);
            prev = cur;
        }
    }
}

/**
 * Angle between two lines, computed purely from their direction vectors, so it is
 * well defined for intersecting, parallel, perpendicular, and skew lines alike.
 * Uses atan2(|cross|, dot) for numerical robustness: the result lands in [0, 180]
 * deg with no wrapping, and parallel/antiparallel resolve to exactly 0/180 deg.
 */
function angleBetweenDirections(d0 is Vector, d1 is Vector, complement is boolean) returns ValueWithUnits
{
    const u0 = normalize(d0);
    const u1 = normalize(d1);

    var theta = atan2(norm(cross(u0, u1)), dot(u0, u1));

    if (complement)
    {
        theta = 180 * degree - theta;
    }
    return theta;
}

/**
 * @internal
 * Editing logic function for populating the displayValue parameter
 */
export function variableEditLogic(context is Context, id is Id, oldDefinition is map, definition is map, isCreating is boolean) returns map
{
    if (definition.mode == VariableMode.ASSIGNED)
    {
        definition.value = switch (definition.variableType) {
                    VariableType.LENGTH : copyParameter("lengthValue"),
                    VariableType.ANGLE : copyParameter("angleValue"),
                    VariableType.NUMBER : copyParameter("numberValue"),
                    VariableType.ANY : copyParameter("anyValue")
                };
    }
    else
    {
        definition.value = "?";
    }

    if (oldDefinition == {} && !isQueryEmpty(context, definition.initEntities))
    {
        if (definition.mode == VariableMode.MEASURED)
        {
            if (definition.measurementMode == VariableMeasurementMode.DISTANCE)
            {
                definition.entityCouple = definition.initEntities;
            }
            else if (definition.measurementMode == VariableMeasurementMode.LENGTH)
            {
                definition.lengthEntities = qUnion(
                  definition.initEntities->qEntityFilter(EntityType.EDGE),
                  definition.initEntities->qBodyType(BodyType.WIRE)
                );
            }
            else if (definition.measurementMode == VariableMeasurementMode.DIAMETER)
            {
                definition.diameterEntity = qUnion([
                    definition.initEntities->qGeometry(GeometryType.CIRCLE),
                    definition.initEntities->qGeometry(GeometryType.ARC),
                    definition.initEntities->qGeometry(GeometryType.CYLINDER),
                    definition.initEntities->qGeometry(GeometryType.SPHERE)
                ])->qNthElement(0);
            }
            else if (definition.measurementMode == VariableMeasurementMode.ANGLE)
            {
                definition.angleEntities = definition.initEntities;
            }
        }
        definition.initEntities = qNothing();
    }

    return definition;
}

function sideContainsConstructionPlanes(context is Context, side) returns boolean
{
    if (side is Query)
    {
        return !isQueryEmpty(context, side->qConstructionFilter(ConstructionObject.YES)->qGeometry(GeometryType.PLANE));
    }
    return false;
}

function getFlatOwnerBody(context is Context, entity is Query)
{
    const smFlatOwnerBodyQuery = qUnion(
        entity->qSheetMetalFlatFilter(SMFlatType.YES)->qOwnerBody(), // regular flat entities
        qPartsAttachedTo(entity) // bend lines
    )->qBodyType(BodyType.SOLID); // solid because sheet metal sketches will get the sketch body and the flat
    return isQueryEmpty(context, smFlatOwnerBodyQuery) ? undefined : smFlatOwnerBodyQuery;
}

function indexMap(indices is array, keyArray is array, valueArray is array)
{
    var result = {};
    for (var index in reverse(indices)) // So earliest index wins
        result[keyArray[index]] = valueArray[index];
    return result;
}

function checkIndex(index is number, a is array, valueToThrow, faultyParameters is array)
{
    check(index >= 0, valueToThrow, faultyParameters);
    check(index < size(a), valueToThrow, faultyParameters);
}

function check(condition is boolean, valueToThrow, faultyParameters is array)
{
    if (!condition)
         throw regenError(valueToThrow, faultyParameters);
}

function matchRegexp(s is string, regExp is string, error is ErrorStringEnum, parameterIds is array)
{
    try silent
    {
        return match(s, regExp).hasMatch;
    }
    catch (e)
    {
        throw regenError(e is ErrorStringEnum ? e : error, parameterIds);
    }
}
